# এসএসসি সাধারণ গণিত অধ্যায় ৩: সমন্বিত সৃজনশীল প্রশ্ন
#  ধরন ১ (১৫টি): ক — ৩.৩ (উৎপাদক), খ — ৩.১ (বর্গের সূত্র), গ — ৩.৩ (উৎপাদক); সহজ ৪, মধ্যম ৮, কঠিন ৩
#  ধরন ২ (৬টি, মধ্যম): ক — ৩.৩ (উৎপাদক), খ ও গ — ৩.৫ (বাস্তব সমস্যা)
# gen_cq_c10_3.py এটি import করে cq_c10_3.json এ b26 থেকে যোগ করে।
import sympy as sp
from sympy import Rational as R, sqrt
x,y,z,a,b,c,u=sp.symbols('x y z a b c u')
E=lambda p,q: sp.expand(p-q)==0
Q=lambda p,q: abs(sp.N(p-q,30))<1e-20
def pair(s,p):  # দুই সংখ্যার যোগফল s, গুণফল p হলে (বড়, ছোট)
    r=sorted(sp.solve(x**2-s*x+p,x),reverse=True); return r

