# সহজ
assert E((x-3)*(x-4),x**2-7*x+12) and pair(5,6)==[3,2] and 25-12==13 and 25-24==1 and E((x**2-3)*(x-2)*(x+2),x**4-7*x**2+12)
t=2+sqrt(3); assert Q(t+1/t,4) and Q(t**2+t**-2,14) and E((a+3*b)*(a-3*b),a**2-9*b**2) and E((a**2+9*b**2)*(a+3*b)*(a-3*b),a**4-81*b**4)
assert E((2*x+1)*(x+3),2*x**2+7*x+3) and 9+20==29 and 29+20==49 and E((2*x+3)*(x+4),2*(x+1)**2+7*(x+1)+3) and pair(7,10)==[5,2]
assert E((x-2)*(x**2+2*x+4),x**3-8) and 36-16==20 and 36-32==4 and pair(6,8)==[4,2] and E((x-2)*(x**2+2*x+4)*(x+2)*(x**2-2*x+4),x**6-64)
# মধ্যম
