t=(sqrt(5)+1)/2; assert Q(t+1/t,sqrt(5)) and Q(t**2+t**-2,3) and Q(t**4+t**-4,7) and E((x+5)*(x-3),x**2+2*x-15) and E((x**2+2*x-5)*(x**2+2*x+3),(x**2+2*x)**2-2*(x**2+2*x)-15)
assert E((a+b-c)*(a-b+c),a**2-b**2+2*b*c-c**2) and 100-62==38 and 2*38-2*31==14 and E(a**2*(b-c)+b**2*(c-a)+c**2*(a-b),-(a-b)*(b-c)*(c-a))
t=(3+sqrt(13))/2; assert Q(t-1/t,3) and Q(t**2+t**-2,11) and Q((t+1/t)**2,13) and E((2*x+1)*(3*x-2),6*x**2-x-2) and E((2*a+b)*(3*a-2*b),6*a**2-a*b-2*b**2)
assert E((x+y+3)*(x-y-3),x**2-y**2-6*y-9) and 64-30==34 and 64-60==4 and pair(8,15)==[5,3] and E((2*x+3*y+2)*(2*x-3*y-2),4*x**2-9*y**2-12*y-4)
t=(3+sqrt(5))/2; assert Q(t+1/t,3) and Q(t**2+t**-2,7) and Q(t**4+t**-4,47) and E((x**2+2*x+2)*(x**2-2*x+2),x**4+4) and E((8*a**2+4*a*b+b**2)*(8*a**2-4*a*b+b**2),64*a**4+b**4)
assert E((x-3)*(x-7),x**2-10*x+21) and 16+42==58 and 58+42==100 and sp.solve([a-b-4,a*b-21,a+b-10],[a,b])==[(7,3)] and E(((x**2-10*x)**2+42*(x**2-10*x)+441),(x-3)**2*(x-7)**2)
assert E((x-y+1)*(x-y-1),x**2+y**2-2*x*y-1) and 49-24==25 and 49-48==1 and E((a+b+c+z)*(a+b-c-z),a**2+2*a*b+b**2-c**2-2*c*z-z**2)
# কঠিন
assert E((x+3)*(x**2-3*x+9),x**3+27) and 36-22==14 and 2*(14-11)==6 and 6*(14-11)==18 and sp.expand((1+2+3)**1)==6 and 1+8+27-3*6==18
assert E((a**2+a+1)*(a**2-a+1),a**4+a**2+1) and Q(((3+sqrt(5))/2)**2+((3+sqrt(5))/2)**-2,7) and Q((3+sqrt(5))/2-2/(3+sqrt(5)),sqrt(5)) and E((a+1)*(a+2)*(a+3)*(a+4)-120,(a**2+5*a+16)*(a+6)*(a-1))
assert E((a-2*b)*(a**2+2*a*b+4*b**2),a**3-8*b**3) and 25+28==53 and 53+28==81 and pair(9,14)==[7,2] and E(a**3-9*b**3+(a+b)**3,(a-b)*(2*a**2+5*a*b+8*b**2))
