assert sorted(sp.solve(x**2-10*x+24,x))==[4,6] and R(1,4)+R(1,6)==R(5,12) and 1/R(5,12)==R(12,5) and R(5,12)-R(1,8)==R(7,24) and 1/R(7,24)==R(24,7)
assert sorted(sp.solve(x**2-13*x+36,x))==[4,9] and (9+4,9-4)==(13,5) and (65/13,65/5)==(5,13) and sp.solve(x/13+x/5-9,x)==[R(65,2)]
assert sorted(sp.solve(x**2-11*x+30,x))==[5,6] and 8000*6*4/100==1920 and 8000*R(105,100)**2==8820 and 8000*6*2/100==960 and 960-820==140
assert sorted(sp.solve(x**2-25*x+100,x))==[5,20] and 20*12==240 and 20*15-240==60 and R(60,240)==R(1,4) and 240*R(125,100)==300 and R(300,16)==R(75,4)

